// Generated by philote from page /authors/[id]. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import { authors } from "@/lib/api";
import { readAuthorView } from "@/lib/reads";

import AuthorView from "@/components/common/author-view";

export const metadata: Metadata = { title: "Author" };

export default function Page({ params }: PageProps<"/authors/[id]">) {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl">
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Record params={params} />
                </Suspense>
            </div>
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/authors/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await authors.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readAuthorView(result.value);
    return <AuthorView {...item} />;
}
